# ---- 10.5 refinement
acc('REQ-501','The refinement scenario of `team.feature` (lead splits, member refines, lead requests review, reviewer completes → `ready`) passes against the registered template.',replace=True)
acc('REQ-504','For each of the five template edit rules one refusing and one passing scenario exist (S-504-1..S-504-10).',replace=True)
for i,(t,patch,cmd,ok,txt) in enumerate([
 ('a note is allowed while the refinement review is frozen','{"status":"refinement review","refiner":""}','--refinement-review complete --comments ok','lead',None),
 ('a field edit before ready is refused','{"status":"refining","refiner":"ann"}','--claim bob','bob','is not ready'),
 ('the owner may close before ready','{"status":"refining","refiner":"ann"}','--close --by owner --reason r --summary s','owner',None),
 ('the lead edits a refining item only as its refiner','{"status":"refining","refiner":"ann"}','--set-estimate 5','lead','refiner'),
 ('the lead may set dependencies of a refining item','{"status":"refining","refiner":"ann"}','--set-depends-on none','lead',None),
 ('a member may not work an incomplete item','{"status":"ready","refiner":""}','--note n','bob','incomplete'),
 ('the owner may close an incomplete item','{"status":"ready","refiner":""}','--close --by owner --reason r --summary s','owner',None),
 ('an estimate line is allowed on an incomplete refining item','{"status":"refining","refiner":"ann"}','--append "ESTIMATE: 5"','ann',None)],3):
  g=BG_TEAM+f'\n  And I run `backlog team new --team t1 --agent lead --name a`\n  And item 1 has the front-matter fields `{patch}`\nWhen I run `backlog team update 1 --team t1 --agent {ok} {cmd}`\n'+('Then the command succeeds' if txt is None else f'Then the command fails with exit code 1\n  And the output contains "{txt}"')
  scen('REQ-504',t,g)
